parameters.jsCode:
const items = $input.all();

const lignes = items
  .map(i => String(i.json.msg_blocage ?? '').replace(/[\r\n\t]+/g, ' ').replace(/ {2,}/g, ' ').trim())
  .filter(Boolean)
  .map((l, idx) => `${idx + 1}. ${l}`);

return [{
  json: {
    to: "212652060652",
    date: new Date().toLocaleDateString('fr-FR', { timeZone: 'Africa/Casablanca' }),
    texte_inline: lignes.join(' | '),
    lignes,
    nb_messages: lignes.length
  }
}];

const groupes = {};

for (const item of $input.all()) {
  const { FactureFrns, Bon_Reception } = item.json;

  if (!groupes[FactureFrns]) {
    groupes[FactureFrns] = new Set();
  }
  groupes[FactureFrns].add(Bon_Reception);
}

return Object.entries(groupes).map(([FactureFrns, brs]) => {
  const liste = [...brs];

  return {
    json: {
      msg_blocage: `Ecart facture et réception : ${FactureFrns}, ${liste.join(', ')} `,
    },
  };
});

